// Website request forms (home audit form and partners page), markup generated by tools/forms.mjs.
// Sends JSON to the same-origin endpoint /api/website-request (nginx proxies it to the Twenty CRM workflow
// webhook). Payload contract: GEMINI.md section 9 / minos-crm/docs/website-form.md. If sending fails, the
// visitor gets a prefilled mailto: link to info@minos.solutions instead.
(function () {
  'use strict';
  var T = {
    en: {
      sending: 'Sending…',
      okH: 'Thank you',
      okP: 'We’ll reply within one business day.',
      err: 'Sorry, we could not send your request. Please try again in a moment, or ',
      errLink: 'send it to us by email',
      errPost: ' (info@minos.solutions).',
    },
    es: {
      sending: 'Enviando…',
      okH: 'Gracias',
      okP: 'Le responderemos en un día hábil.',
      err: 'Lo sentimos, no pudimos enviar su solicitud. Inténtelo de nuevo en un momento, o ',
      errLink: 'envíenosla por correo',
      errPost: ' (info@minos.solutions).',
    },
  };
  var UTM = ['source', 'medium', 'campaign', 'term', 'content'];

  // Campaign tags: from this page's URL if present, otherwise from earlier in the visit (saved by the layout script).
  function readUtm() {
    var u = {}, any = false;
    try {
      var q = new URLSearchParams(location.search);
      UTM.forEach(function (k) { var v = q.get('utm_' + k); if (v) { u[k] = v.slice(0, 200); any = true; } });
    } catch (e) { /* old browser */ }
    if (any) { try { sessionStorage.setItem('minos_utm', JSON.stringify(u)); } catch (e) { /* storage unavailable */ } }
    else { try { u = JSON.parse(sessionStorage.getItem('minos_utm') || '{}') || {}; } catch (e) { u = {}; } }
    var out = {};
    UTM.forEach(function (k) { out[k] = typeof u[k] === 'string' ? u[k] : ''; });
    return out;
  }

  var clean = function (s) { return String(s == null ? '' : s).replace(/\s+/g, ' ').trim(); };

  function setup(form) {
    var t0 = Date.now();
    var utm = readUtm();
    var lang = form.getAttribute('data-lang') === 'es' ? 'es' : 'en';
    var L = T[lang];
    var btn = form.querySelector('button[type="submit"]');
    var btnText = btn.textContent;
    var status = form.querySelector('.form-status');

    var field = function (n) { return form.querySelector('[name="' + n + '"]'); };
    var val = function (n) { var el = field(n); return el ? String(el.value || '').trim() : ''; };
    var checked = function (n) {
      return Array.prototype.map.call(form.querySelectorAll('input[name="' + n + '"]:checked'), function (x) { return x.value; });
    };

    function payload() {
      var interest = val('interest');
      var consentEl = form.querySelector('.consent-text');
      var p = {
        interest: interest,
        name: val('name'), email: val('email'), jobTitle: val('jobTitle'), organization: val('organization'),
        website: val('website'), country: val('country'), city: val('city'), phone: val('phone'), message: val('message'),
        consent: true,
        consentText: consentEl ? clean(consentEl.textContent) : '',
        lang: lang,
        page: location.pathname,
        utm: utm,
        hp: val('company_url'),
        elapsedMs: Date.now() - t0,
      };
      if (interest === 'client') {
        var cc = parseInt(val('campusCount'), 10);
        p.institutionType = val('institutionType');
        p.area = val('area');
        p.studentRange = val('studentRange');
        p.campusCount = isFinite(cc) && cc > 0 ? cc : null;
        p.channels = checked('channels');
      } else if (interest === 'partner') {
        p.companyType = val('companyType');
        p.collaboration = checked('collaboration');
        p.institutionsServed = val('institutionsServed');
        p.countriesServed = val('countriesServed');
      }
      return p;
    }

    // Fallback e-mail: every visible field as "Label: answer" (localized labels and option texts), message last.
    function mailto() {
      var lines = [], msg = '';
      Array.prototype.forEach.call(form.querySelectorAll('.form-group'), function (g) {
        if (g.classList.contains('consent')) return;
        var lab = g.querySelector('legend') || g.querySelector('label');
        if (!lab) return;
        var name = clean(lab.textContent).replace(/\s*\*$/, '');
        var v;
        if (g.querySelector('textarea')) { msg = g.querySelector('textarea').value.trim(); return; }
        if (g.querySelector('select')) { var s = g.querySelector('select'); v = s.value ? s.options[s.selectedIndex].text : ''; }
        else if (g.querySelector('input[type="checkbox"]')) {
          v = Array.prototype.map.call(g.querySelectorAll('input:checked'), function (x) { return clean(x.parentNode.textContent); }).join(', ');
        } else if (g.querySelector('input')) { v = g.querySelector('input').value.trim(); }
        else return;
        if (v) lines.push(name + ': ' + v);
      });
      if (msg) lines.push('', msg);
      var subject = (form.getAttribute('data-subject') || '') + (val('organization') ? ' - ' + val('organization') : '');
      return 'mailto:info@minos.solutions?subject=' + encodeURIComponent(subject) + '&body=' + encodeURIComponent(lines.join('\n'));
    }

    function fail() {
      btn.disabled = false;
      btn.textContent = btnText;
      status.textContent = '';
      status.appendChild(document.createTextNode(L.err));
      var a = document.createElement('a');
      a.href = mailto();
      a.textContent = L.errLink;
      status.appendChild(a);
      status.appendChild(document.createTextNode(L.errPost));
      status.hidden = false;
    }

    function done() {
      var box = document.createElement('div');
      box.className = 'form-success';
      box.setAttribute('role', 'status');
      box.setAttribute('tabindex', '-1');
      var h = document.createElement('h3'); h.textContent = L.okH;
      var p = document.createElement('p'); p.textContent = L.okP;
      box.appendChild(h); box.appendChild(p);
      form.parentNode.replaceChild(box, form);
      box.focus();
    }

    form.addEventListener('submit', function (e) {
      e.preventDefault();
      if (btn.disabled) return;
      if (form.reportValidity && !form.reportValidity()) return;
      status.hidden = true;
      btn.disabled = true;
      btn.textContent = L.sending;
      var body;
      try { body = JSON.stringify(payload()); } catch (err) { fail(); return; }
      if (!window.fetch) { fail(); return; }
      fetch('/api/website-request', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: body, credentials: 'same-origin' })
        .then(function (res) { if (res.ok) done(); else fail(); })
        .catch(fail);
    });
  }

  function init() { Array.prototype.forEach.call(document.querySelectorAll('form.request-form'), setup); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();
